}

function convertCarriedUnpaidToDebt(world, actorId, shopkeeperId, reason) {
  const converted = [];
  for (const itemId of inventoryItems(world, actorId)) {
    const unpaid = world.get(itemId, Unpaid);
    if (!unpaid || unpaid.shopkeeperId !== shopkeeperId) continue;
