      name: "",
    });
    try { world.remove(itemId, Unpaid); } catch {}
    if (debt) converted.push(debt);
  }
  return converted;
}

function itemIdentity(world, itemId) {
  const ni = world.get(itemId, /** @type any */ (null));
  return String(ni?.identity || "");
}

export function enforceShopEscape(world, {
  actorId,
  from,
  to = null,
  source = "escape",
} = {}) {
  const actor = Number(actorId || 0) | 0;
  if (!(actor > 0) || !from) return null;
