  if (!room) return null;
  if (to && shopAt(world, to.x, to.y)?.shopkeeperId === room.shopkeeperId) return null;

  const before = evaluateShopExitClaim(world, { actorId: actor, shopkeeperId: room.shopkeeperId });
  if (before.bill <= 0) return null;

  const converted = [];
  for (const itemId of inventoryItems(world, actor)) {
    const unpaid = world.get(itemId, Unpaid);
    if (!unpaid || unpaid.shopkeeperId !== room.shopkeeperId) continue;
    const debt = recordShopDebt(world, {
      actorId: actor,
      shopkeeperId: room.shopkeeperId,
      amount: unpaid.price,
      reason: "shoplifting",
      itemId,
      identity: itemIdentity(world, itemId),
      name: "",
    });
    try { world.remove(itemId, Unpaid); } catch {}
    if (debt) converted.push(debt);
  }

  const after = evaluateShopExitClaim(world, { actorId: actor, shopkeeperId: room.shopkeeperId });
  const event = {
    actor,
    shopkeeperId: room.shopkeeperId,
    bill: after.bill,
    decision: {
      ...after,
      kind: SHOP_ENFORCEMENT_DECISIONS.debtRefused,
      blocksExit: false,
      reasons: Object.freeze([...(after.reasons || []), "escaped_claim"]),
    },
    convertedDebts: Object.freeze(converted),
    source: String(source || "escape"),
    from: { x: Number(from.x) | 0, y: Number(from.y) | 0 },
    to: to ? { x: Number(to.x) | 0, y: Number(to.y) | 0 } : null,
  };
  try { world.emit?.("shop:claim-escaped", event); } catch {}
  try { world.emit?.("shop:claim-enforced", event); } catch {}
  return event;
}

export function installShopEscapeListeners(world) {
  if (!world || world[ESCAPE_LISTENERS_INSTALLED]) return;
  world[ESCAPE_LISTENERS_INSTALLED] = true;

