import { Alignment } from "../components/Alignment.js";
import { ItemInfo } from "../components/ItemInfo.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { Position } from "../components/Position.js";
import { RoomMetadata } from "../components/RoomMetadata.js";
import { Unpaid } from "../components/Unpaid.js";
import { inventoryItems } from "./inventoryFacade.js";
import { calculateShopDebt, recordShopDebt, shopDebtRecords } from "./shopDebt.js";

export const SHOP_ENFORCEMENT_DECISIONS = Object.freeze({
  allow: "allow",
  demandPayment: "demand_payment",
  creditExtended: "credit_extended",
  containment: "containment",
  debtRefused: "debt_refused",
});

const ESCAPE_LISTENERS_INSTALLED = Symbol.for("jshack:shopEnforcement:escapeListeners:installed");

export function calculateCarriedUnpaidBill(world, actorId, shopkeeperId) {
  let total = 0;
  for (const itemId of inventoryItems(world, actorId)) {
    const unpaid = world.get(itemId, Unpaid);
    if (unpaid && unpaid.shopkeeperId === shopkeeperId) total += unpaid.price;
  }
  return total;
}

export function countCarriedUnpaidItems(world, actorId, shopkeeperId) {
  let count = 0;
  for (const itemId of inventoryItems(world, actorId)) {
    const unpaid = world.get(itemId, Unpaid);
    if (unpaid && unpaid.shopkeeperId === shopkeeperId) count += 1;
  }
  return count;
}

export function countGold(world, actorId) {
  let total = 0;
  for (const id of inventoryItems(world, actorId)) {
    const info = world.get(id, ItemInfo);
    if (info && info.type === "currency") total += Math.max(0, Number(info.count || 0));
  }
  return total;
}

function alignmentCreditBonus(world, actorId) {
  const alignment = world.get(actorId, Alignment);
  let bonus = 0;
  if (alignment?.lawChaos === "lawful") bonus += 20;
  if (alignment?.lawChaos === "chaotic") bonus -= 20;
  if (alignment?.goodEvil === "good") bonus += 10;
  if (alignment?.goodEvil === "evil") bonus -= 10;
  return bonus;
}

function oldestDebtAge(world, debts) {
  const now = Number(world.step || 0) | 0;
  let oldest = 0;
  for (const debt of debts) {
    const age = Math.max(0, now - (Number(debt?.createdTurn ?? debt?.turn ?? now) | 0));
    if (age > oldest) oldest = age;
  }
  return oldest;
}

export function evaluateShopExitClaim(world, {
  actorId,
  shopkeeperId,
  policy = {},
} = {}) {
  const actor = Number(actorId || 0) | 0;
  const shopkeeper = Number(shopkeeperId || 0) | 0;
  const carriedBill = calculateCarriedUnpaidBill(world, actor, shopkeeper);
  const debtTotal = calculateShopDebt(world, actor, shopkeeper);
  const bill = carriedBill + debtTotal;
  const carriedCount = countCarriedUnpaidItems(world, actor, shopkeeper);
  const debtRecords = shopDebtRecords(world, actor, shopkeeper);
  const debtCount = debtRecords.length;
  const debtAge = oldestDebtAge(world, debtRecords);
  const gold = countGold(world, actor);
  const canPay = gold >= bill;

  const trustedCreditLimit = Math.max(0, Number(policy.trustedCreditLimit ?? 75));
  const baseCreditLimit = Math.max(0, Number(policy.creditLimit ?? 25));
  const debtAgePenalty = Math.floor(debtAge / Math.max(1, Number(policy.agePenaltyTurns ?? 25))) * 10;
  const creditScore = alignmentCreditBonus(world, actor)
    - Math.max(0, bill - baseCreditLimit)
    - Math.max(0, debtCount - 1) * 20
    - carriedCount * 15
    - debtAgePenalty;

  const reasons = [];
  if (carriedBill > 0) reasons.push("carried_unpaid_goods");
  if (debtTotal > 0) reasons.push("unpaid_extracted_value");
  if (debtCount > 1) reasons.push("repeat_debt");
  if (debtAge > 0) reasons.push("aged_debt");
  if (canPay) reasons.push("can_pay_now");
  else if (bill > 0) reasons.push("cannot_pay_now");

  if (bill <= 0) {
    return Object.freeze({
      kind: SHOP_ENFORCEMENT_DECISIONS.allow,
      blocksExit: false,
      bill,
      carriedBill,
      debtTotal,
      carriedCount,
      debtCount,
      debtAge,
      gold,
      canPay,
      creditScore,
      reasons: Object.freeze(reasons),
    });
  }

  let kind = SHOP_ENFORCEMENT_DECISIONS.containment;
  let blocksExit = true;
  if (canPay) {
    kind = SHOP_ENFORCEMENT_DECISIONS.demandPayment;
  } else if (carriedBill <= 0 && debtTotal <= trustedCreditLimit && creditScore >= 0) {
    kind = SHOP_ENFORCEMENT_DECISIONS.creditExtended;
    blocksExit = false;
  } else if (debtAge >= Number(policy.refusalAgeTurns ?? 50) || debtCount >= Number(policy.refusalDebtCount ?? 3)) {
    kind = SHOP_ENFORCEMENT_DECISIONS.debtRefused;
  }

  return Object.freeze({
    kind,
    blocksExit,
    bill,
    carriedBill,
    debtTotal,
    carriedCount,
    debtCount,
    debtAge,
    gold,
    canPay,
    creditScore,
    reasons: Object.freeze(reasons),
  });
}

export function shopEnforcementLine(decision) {
  const kind = String(decision?.kind || "");
  const bill = Math.max(0, Number(decision?.bill || 0) | 0);
  const reasons = Array.isArray(decision?.reasons) ? decision.reasons : [];
  const escaped = reasons.includes("escaped_claim");
  if (escaped) return `You still owe me ${bill} gold. Run if you like. Debts have long legs.`;
  if (kind === SHOP_ENFORCEMENT_DECISIONS.creditExtended) {
    return `You owe me ${bill} gold. I expect you to settle this.`;
  }
  if (kind === SHOP_ENFORCEMENT_DECISIONS.debtRefused) {
    return `You have had long enough. Pay ${bill} gold.`;
  }
  if (kind === SHOP_ENFORCEMENT_DECISIONS.containment) {
    return `Not so fast. You owe me ${bill} gold.`;
  }
  if (kind === SHOP_ENFORCEMENT_DECISIONS.demandPayment) {
    return `You owe me ${bill} gold.`;
  }
  return "";
}

function shopAt(world, x, y) {
  const tx = Number(x) | 0;
  const ty = Number(y) | 0;
  for (const [, room] of world.query(RoomMetadata)) {
    if (room.roomType !== "shop" || !(room.shopkeeperId > 0)) continue;
    if (tx >= room.x && tx < room.x + room.w && ty >= room.y && ty < room.y + room.h) return room;
  }
  return null;
}

function convertCarriedUnpaidToDebt(world, actorId, shopkeeperId) {
  const converted = [];
  for (const itemId of inventoryItems(world, actorId)) {
    const unpaid = world.get(itemId, Unpaid);
    if (!unpaid || unpaid.shopkeeperId !== shopkeeperId) continue;
    const debt = recordShopDebt(world, {
      actorId,
      shopkeeperId,
      amount: unpaid.price,
      reason: "shoplifting",
      itemId,
      identity: world.get(itemId, NamedIdentity)?.identity || "",
      name: world.get(itemId, NamedIdentity)?.name || "",
    });
    try { world.remove(itemId, Unpaid); } catch {}
    if (debt) converted.push(debt);
  }
  return converted;
}

export function enforceShopEscape(world, {
  actorId,
  from,
  to = null,
  source = "escape",
} = {}) {
  const actor = Number(actorId || 0) | 0;
  if (!(actor > 0) || !from) return null;

  const room = shopAt(world, from.x, from.y);
  if (!room) return null;
  if (to && shopAt(world, to.x, to.y)?.shopkeeperId === room.shopkeeperId) return null;

  const before = evaluateShopExitClaim(world, { actorId: actor, shopkeeperId: room.shopkeeperId });
  if (before.bill <= 0) return null;

  const convertedDebts = convertCarriedUnpaidToDebt(world, actor, room.shopkeeperId);
  const after = evaluateShopExitClaim(world, { actorId: actor, shopkeeperId: room.shopkeeperId });
  const decision = Object.freeze({
    ...after,
    kind: SHOP_ENFORCEMENT_DECISIONS.debtRefused,
    blocksExit: false,
    reasons: Object.freeze([...(after.reasons || []), "escaped_claim"]),
  });
  const event = Object.freeze({
    actor,
    shopkeeperId: room.shopkeeperId,
    bill: after.bill,
    decision,
    convertedDebts: Object.freeze(convertedDebts),
    source: String(source || "escape"),
    from: Object.freeze({ x: Number(from.x) | 0, y: Number(from.y) | 0 }),
    to: to ? Object.freeze({ x: Number(to.x) | 0, y: Number(to.y) | 0 }) : null,
  });

  try { world.emit?.("shop:claim-escaped", event); } catch {}
  try { world.emit?.("shop:claim-enforced", event); } catch {}
  const line = shopEnforcementLine(decision);
  if (line) {
    try {
      world.emit?.("npc:dialogue", {
        actor: room.shopkeeperId,
        targetId: actor,
        text: line,
        source: "shop:claim-escaped",
      });
    } catch {}
  }
  return event;
}

export function installShopEscapeListeners(world) {
  if (!world || world[ESCAPE_LISTENERS_INSTALLED]) return;
  world[ESCAPE_LISTENERS_INSTALLED] = true;

  world.on("teleported", ({ id, actor, from, to, source }) => {
    enforceShopEscape(world, {
      actorId: Number(id || actor || 0) | 0,
      from,
      to,
      source: source || "teleported",
    });
  });

  world.on("spell:blink", ({ actor, from, to }) => {
    enforceShopEscape(world, { actorId: actor, from, to, source: "spell:blink" });
  });

  world.on("spell:phase_strike", ({ actor, from, to }) => {
    enforceShopEscape(world, { actorId: actor, from, to, source: "spell:phase_strike" });
  });

  world.on("dungeon:teleport-depth", ({ actor, source }) => {
    const actorId = Number(actor || 0) | 0;
    const pos = actorId > 0 ? world.get(actorId, Position) : null;
    enforceShopEscape(world, {
      actorId,
      from: pos,
      to: null,
      source: source || "dungeon:teleport-depth",
    });
  });
}

